      inner join "asset" on "asset"."id" = "asset_face"."assetId"
      inner join "face_search" on "face_search"."faceId" = "asset_face"."id"
      left join "person" on "person"."personGroupId" = "asset_face"."personGroupId"
    where
      "asset"."ownerId" = any ($2::uuid[])
      and "asset"."deletedAt" is null
      and "asset"."visibility" in ($3, $4)
      and "asset_face"."deletedAt" is null
    order by
      "distance"
    limit
      $5
  )
select
  *
from
  "cte"
where
  "cte"."distance" <= $6
commit

-- SearchRepository.searchPlaces
select
  *
from
  "geodata_places"
where
  f_unaccent (name) %>> f_unaccent ($1)
  or f_unaccent ("admin2Name") %>> f_unaccent ($2)
  or f_unaccent ("admin1Name") %>> f_unaccent ($3)
  or f_unaccent ("alternateNames") %>> f_unaccent ($4)
order by
  coalesce(f_unaccent (name) <->>> f_unaccent ($5), 0.1) + coalesce(
    f_unaccent ("admin2Name") <->>> f_unaccent ($6),
    0.1
  ) + coalesce(
    f_unaccent ("admin1Name") <->>> f_unaccent ($7),
    0.1
  ) + coalesce(
    f_unaccent ("alternateNames") <->>> f_unaccent ($8),
    0.1
  )
limit
  $9

-- SearchRepository.getAssetsByCity
with recursive
  "cte" as (
    (
      select
        "city",
        "assetId"
      from
        "asset_exif"
        inner join "asset" on "asset"."id" = "asset_exif"."assetId"
      where
        (
          "asset"."ownerId" = any ($1::uuid[])
          or exists (
            select
              1 as "exists"
            from
              "shared_space_asset"
            where
              "shared_space_asset"."assetId" = "asset"."id"
              and "shared_space_asset"."spaceId" = any ($2::uuid[])
          )
          or exists (
            select
              1 as "exists"
            from
              "shared_space_library"
            where
              "shared_space_library"."libraryId" = "asset"."libraryId"
              and "shared_space_library"."spaceId" = any ($3::uuid[])
          )
          or (
            exists (
              select
                1 as "exists"
              from
                "shared_space_album"
                inner join "album_asset" on "album_asset"."albumId" = "shared_space_album"."albumId"
                inner join "album" on "album"."id" = "shared_space_album"."albumId"
                and "album"."deletedAt" is null
              where
                "album_asset"."assetId" = "asset"."id"
                and "shared_space_album"."spaceId" = any ($4::uuid[])
                and "shared_space_album"."showInTimeline" = $5
            )
            or exists (
              select
                1 as "exists"
              from
                "shared_space_album"
                inner join "album_space_asset" on "album_space_asset"."albumId" = "shared_space_album"."albumId"
                and "album_space_asset"."spaceId" = "shared_space_album"."spaceId"
                inner join "album" on "album"."id" = "shared_space_album"."albumId"
                and "album"."deletedAt" is null
              where
                "album_space_asset"."assetId" = "asset"."id"
                and "shared_space_album"."spaceId" = any ($6::uuid[])
                and "shared_space_album"."showInTimeline" = $7
            )
          )
        )
        and "asset"."visibility" = $8
        and "asset"."type" = $9
        and "asset"."deletedAt" is null
      order by
        "city"
      limit
        $10
    )
    union all
    (
      select
        "l"."city",
        "l"."assetId"
      from
        "cte"
        inner join lateral (
          select
            "city",
            "assetId"
          from
            "asset_exif"
            inner join "asset" on "asset"."id" = "asset_exif"."assetId"
          where
            (
              "asset"."ownerId" = any ($11::uuid[])
              or exists (
                select
                  1 as "exists"
                from
                  "shared_space_asset"
                where
                  "shared_space_asset"."assetId" = "asset"."id"
                  and "shared_space_asset"."spaceId" = any ($12::uuid[])
              )
              or exists (
                select
                  1 as "exists"
                from
                  "shared_space_library"
                where
                  "shared_space_library"."libraryId" = "asset"."libraryId"
                  and "shared_space_library"."spaceId" = any ($13::uuid[])
              )
              or (
                exists (
                  select
                    1 as "exists"
                  from
                    "shared_space_album"
                    inner join "album_asset" on "album_asset"."albumId" = "shared_space_album"."albumId"
                    inner join "album" on "album"."id" = "shared_space_album"."albumId"
                    and "album"."deletedAt" is null
                  where
                    "album_asset"."assetId" = "asset"."id"
                    and "shared_space_album"."spaceId" = any ($14::uuid[])
                    and "shared_space_album"."showInTimeline" = $15
                )
                or exists (
                  select
                    1 as "exists"
                  from
                    "shared_space_album"
                    inner join "album_space_asset" on "album_space_asset"."albumId" = "shared_space_album"."albumId"
                    and "album_space_asset"."spaceId" = "shared_space_album"."spaceId"
                    inner join "album" on "album"."id" = "shared_space_album"."albumId"
                    and "album"."deletedAt" is null
                  where
                    "album_space_asset"."assetId" = "asset"."id"
                    and "shared_space_album"."spaceId" = any ($16::uuid[])
                    and "shared_space_album"."showInTimeline" = $17
                )
              )
            )
            and "asset"."visibility" = $18
            and "asset"."type" = $19
            and "asset"."deletedAt" is null
            and "asset_exif"."city" > "cte"."city"
          order by
            "city"
          limit
            $20
        ) as "l" on true
    )
  )
select
  "asset"."id",
  "asset"."updateId",
  "asset"."createdAt",
  "asset"."updatedAt",
  "asset"."deletedAt",
  "asset"."status",
  "asset"."checksum",
  "asset"."checksumAlgorithm",
  "asset"."duplicateId",
  "asset"."duration",
  "asset"."fileCreatedAt",
  "asset"."fileModifiedAt",
  "asset"."isExternal",
  "asset"."isFavorite",
  "asset"."isOffline",
  "asset"."isEdited",
  "asset"."visibility",
  "asset"."libraryId",
  "asset"."livePhotoVideoId",
  "asset"."localDateTime",
  "asset"."originalFileName",
  "asset"."originalPath",
  "asset"."ownerId",
  "asset"."stackId",
  "asset"."thumbhash",
  "asset"."type",
  "asset"."width",
  "asset"."height",
  to_jsonb("asset_exif") as "exifInfo"
from
  "asset"
  inner join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
  inner join "cte" on "asset"."id" = "cte"."assetId"
order by
  "asset_exif"."city"

