  "asset"."updateId",
  "asset"."createdAt",
  "asset"."updatedAt",
  "asset"."deletedAt",
  "asset"."status",
  "asset"."checksum",
  "asset"."checksumAlgorithm",
  "asset"."duplicateId",
  "asset"."duration",
  "asset"."fileCreatedAt",
  "asset"."fileModifiedAt",
  "asset"."isExternal",
  "asset"."isFavorite",
  "asset"."isOffline",
  "asset"."isEdited",
  "asset"."visibility",
  "asset"."libraryId",
  "asset"."livePhotoVideoId",
  "asset"."localDateTime",
  "asset"."originalFileName",
  "asset"."originalPath",
  "asset"."ownerId",
  "asset"."stackId",
  "asset"."thumbhash",
  "asset"."type",
  "asset"."width",
  "asset"."height"
from
  "asset"
  left join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
where
  (
    "asset"."visibility" != $1
    or "asset"."ownerId" = $2
  )
  and (
    "asset"."fileCreatedAt" < $3
    and "asset"."fileCreatedAt" >= $4
    and (
      (
        "asset"."isFavorite" = $5
        and "asset"."ownerId" = any ($6::uuid[])
      )
      or exists (
        select
        from
          "album_asset"
        where
          "album_asset"."assetId" = "asset"."id"
          and "album_asset"."albumId" = any ($7::uuid[])
      )
    )
  )
order by
  "asset"."fileCreatedAt" desc,
  "asset"."id" desc
limit
  $8
offset
  $9

