                  inner join "album" on "album"."id" = "shared_space_album"."albumId"
                  and "album"."deletedAt" is null
                where
                  "album_asset"."assetId" = "asset"."id"
                  and "shared_space_album"."spaceId" = any ($5::uuid[])
