                  and "album"."deletedAt" is null
                where
                  "album_space_asset"."assetId" = "asset"."id"
                  and "shared_space_album"."spaceId" = any ($7::uuid[])
                  and "shared_space_album"."showInTimeline" = $8
              )
            )
          )
        )
      )
      and "asset"."fileCreatedAt" >= $9
      and exists (
